-- 049: Lake Winnepesaukah, Rossville, Georgia (Carter, 2026-10-17, from RCDB;
-- 34.97650182889069, -85.2458909437384). Not in D1 before.
--   Cannon Ball              PTC wood, 1967, 2,272 ft, 70 ft, 50 mph
--   Wacky Worm               Fajume Wacky Worm, 1991 -> Wacky Worms category
--   Wild Lightnin'           L&T Wild Mouse, 2001-2021; formerly Wild Thing.
--                            RCDB: it became Cheddar Chase at Alabama
--                            Adventure (#815), so the two are linked, home
--                            there. Only Cheddar Chase has a rider; no count moves.
--   Lookout Mountain Safari  Zierer Tivoli (medium), opening 2027 -> Zierer
--                            Tivolis. Stored with a 2027 opening, the way
--                            Werewolf Gorge and Fast & Furious already are.
--                            RCDB: formerly Kombo at Indianapolis Zoo (not in D1).
-- Also Alabama Adventure's pin moves to the coordinates Carter sent the same
-- day (33.38182956092658, -86.9991891002; was 33.3800285, -86.999068).
-- /changes rows in the Worker's shapes. Safe to run twice.
INSERT INTO parks (name, lat, lon, region) SELECT 'Lake Winnepesaukah', 34.97650182889069, -85.2458909437384, 'Georgia, US' WHERE NOT EXISTS (SELECT 1 FROM parks WHERE name = 'Lake Winnepesaukah');
INSERT INTO coasters (id, name, park, type, manu, model, h, s, l, inv, dur, laps, yr, opened, openedPrec, closed, closedPrec) SELECT (SELECT COALESCE(MAX(id),0)+1 FROM coasters), 'Cannon Ball', 'Lake Winnepesaukah', 'Wood', 'Philadelphia Toboggan Coasters', 'PTC Wood', 70, 50, 2272, 0, NULL, 1, 1967, '1967', 'year', NULL, NULL WHERE EXISTS (SELECT 1 FROM parks WHERE name = 'Lake Winnepesaukah') AND NOT EXISTS (SELECT 1 FROM coasters WHERE name = 'Cannon Ball' AND park = 'Lake Winnepesaukah');
INSERT INTO coasters (id, name, park, type, manu, model, h, s, l, inv, dur, laps, yr, opened, openedPrec, closed, closedPrec) SELECT (SELECT COALESCE(MAX(id),0)+1 FROM coasters), 'Wacky Worm', 'Lake Winnepesaukah', 'Steel', 'Fajume', 'Wacky Worm', NULL, NULL, NULL, 0, NULL, 1, 1991, '1991', 'year', NULL, NULL WHERE EXISTS (SELECT 1 FROM parks WHERE name = 'Lake Winnepesaukah') AND NOT EXISTS (SELECT 1 FROM coasters WHERE name = 'Wacky Worm' AND park = 'Lake Winnepesaukah');
INSERT INTO coasters (id, name, park, type, manu, model, h, s, l, inv, dur, laps, yr, opened, openedPrec, closed, closedPrec) SELECT (SELECT COALESCE(MAX(id),0)+1 FROM coasters), 'Wild Lightnin''', 'Lake Winnepesaukah', 'Steel', 'L&T Systems', 'L&T Wild Mouse', NULL, NULL, NULL, 0, NULL, 1, 2001, '2001', 'year', '2021', 'year' WHERE EXISTS (SELECT 1 FROM parks WHERE name = 'Lake Winnepesaukah') AND NOT EXISTS (SELECT 1 FROM coasters WHERE name = 'Wild Lightnin''' AND park = 'Lake Winnepesaukah');
INSERT INTO coasters (id, name, park, type, manu, model, h, s, l, inv, dur, laps, yr, opened, openedPrec, closed, closedPrec) SELECT (SELECT COALESCE(MAX(id),0)+1 FROM coasters), 'Lookout Mountain Safari', 'Lake Winnepesaukah', 'Steel', 'Zierer', 'Zierer Tivoli', 19.7, 19.9, 652.9, 0, NULL, 1, 2027, '2027', 'year', NULL, NULL WHERE EXISTS (SELECT 1 FROM parks WHERE name = 'Lake Winnepesaukah') AND NOT EXISTS (SELECT 1 FROM coasters WHERE name = 'Lookout Mountain Safari' AND park = 'Lake Winnepesaukah');
INSERT OR IGNORE INTO coaster_aliases (coaster_id, former_name, note, added) SELECT id, 'Wild Thing', 'rcdb', date('now') FROM coasters WHERE name = 'Wild Lightnin''' AND park = 'Lake Winnepesaukah';
INSERT OR IGNORE INTO clone_members (coaster, group_id) SELECT c.id, g.id FROM coasters c, clone_groups g WHERE c.park = 'Lake Winnepesaukah' AND ((g.name = 'Wacky Worms' AND c.name = 'Wacky Worm') OR (g.name = 'Zierer Tivolis' AND c.name = 'Lookout Mountain Safari'));
INSERT OR IGNORE INTO same_ride (coaster, ride) SELECT x.id, h.id FROM coasters h, coasters x WHERE h.name = 'Cheddar Chase' AND h.park = 'Alabama Adventure' AND ((x.name = 'Wild Lightnin''' AND x.park = 'Lake Winnepesaukah') OR x.id = h.id);
UPDATE parks SET lat = 33.38182956092658, lon = -86.9991891002 WHERE name = 'Alabama Adventure';
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'coaster_added', c.name, NULL, json_object('id', c.id, 'park', c.park) FROM coasters c WHERE c.park = 'Lake Winnepesaukah' AND NOT EXISTS (SELECT 1 FROM activity a WHERE a.kind = 'coaster_added' AND a.subject = c.name AND json_extract(a.detail, '$.park') = 'Lake Winnepesaukah');
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'clone_set', g.name, (SELECT COUNT(*) FROM clone_members m WHERE m.group_id = g.id), json_object('made', 0, 'via', '049') FROM clone_groups g WHERE g.name IN ('Wacky Worms', 'Zierer Tivolis') AND NOT EXISTS (SELECT 1 FROM activity a WHERE a.kind = 'clone_set' AND a.subject = g.name AND a.detail LIKE '%"via":"049"%');
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'same_ride_set', h.name, (SELECT COUNT(*) FROM same_ride s WHERE s.ride = h.id), json_object('ride', h.id, 'at', (SELECT json_group_array(json_object('id', c.id, 'park', c.park, 'name', c.name)) FROM coasters c JOIN same_ride s ON s.coaster = c.id WHERE s.ride = h.id), 'via', '049') FROM coasters h WHERE h.name = 'Cheddar Chase' AND h.park = 'Alabama Adventure' AND (SELECT COUNT(*) FROM same_ride s WHERE s.ride = h.id) = 2 AND NOT EXISTS (SELECT 1 FROM activity a WHERE a.kind = 'same_ride_set' AND a.detail LIKE '%"via":"049"%');
